from rest_framework.throttling import SimpleRateThrottle
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status

class AccountExportRateThrottle(SimpleRateThrottle):
    scope = 'account_export'

    def get_cache_key(self, request, view):
        # Derive throttle identity strictly from the authenticated user's verified account
        if not request.user or not request.user.is_authenticated:
            return None
        return self.cache_format % {'scope': self.scope, 'ident': request.user.account_id}

class AccountDataExportView(APIView):
    permission_classes = [permissions.IsAuthenticated]
    throttle_classes = [AccountExportRateThrottle]

    def post(self, request):
        account_id = request.user.account_id
        return Response({"status": "Export queued", "account_id": account_id})
